CREATE TABLE IF NOT EXISTS portfolio_records (
 id TEXT PRIMARY KEY, collection TEXT NOT NULL CHECK(collection IN ('profile','skills','certifications','projects','experience','education')),
 data TEXT NOT NULL CHECK(json_valid(data)), position INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 1 CHECK(published IN (0,1)),
 updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS records_collection ON portfolio_records(collection,position);
CREATE TABLE IF NOT EXISTS portfolio_admin (
 id INTEGER PRIMARY KEY CHECK(id=1), email TEXT NOT NULL UNIQUE,
 password_hash TEXT, salt TEXT, setup_hash TEXT, activated_at TEXT
);
CREATE TABLE IF NOT EXISTS portfolio_sessions (
 token_hash TEXT PRIMARY KEY, admin_id INTEGER NOT NULL REFERENCES portfolio_admin(id), expires_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS session_expiry ON portfolio_sessions(expires_at);
CREATE TABLE IF NOT EXISTS portfolio_contacts (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, subject TEXT NOT NULL DEFAULT '',
 message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','read','replied','archived')),
 created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS contacts_created ON portfolio_contacts(created_at DESC);
CREATE TABLE IF NOT EXISTS portfolio_rate_limits (
 key TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires_at INTEGER NOT NULL
);
