INSERT OR IGNORE INTO portfolio_records(id,collection,data,position,published) VALUES ('profile','profile','{"name": "Govinda Lamsal", "title": "Cloud Solution Architect, Full-stack Developer & Cloud Trainer.", "location": "Kathmandu, Nepal", "tagline": "Turning ambitious ideas into scalable, data-driven digital solutions.", "about": ["I design the cloud behind the product, build the experience in front of it, and help others understand how it all works.", "As a Cloud Solution Architect at TekBay Academy, I bring together AWS cloud architecture, full-stack development and data science to create scalable, data-driven digital solutions with real-world impact.", "My approach connects hands-on engineering with clear communication: translate a business need into an architecture, turn that architecture into a useful product, and make the knowledge accessible through practical cloud training."], "email": "lamsalgovinda25@gmail.com", "phone": "9841056120", "github": "https://github.com/lamsal25", "linkedin": "https://www.linkedin.com/in/lamsal25/"}',0,1);
